"""Render the standalone prompt dashboard from current manifest and Markdown."""
from pathlib import Path
import json
P=Path(__file__).resolve().parents[1]
m=json.loads((P/'manifest.json').read_text())
for t in m['tasks']:t['prompt']=(P/t['prompt_path']).read_text()
payload=json.dumps(m,ensure_ascii=False).replace('<','\\u003c')
page='''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FC東京×柏｜制作指示・最新の進行状況</title><style>
:root{--ink:#223943;--muted:#64736e;--paper:#fffdf8;--line:#d6ded5;--green:#176154;--pale:#e6f2e9;--orange:#8c651c}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:75px}body{margin:0;background:#f0f2ee;color:var(--ink);font:15px/1.75 system-ui,-apple-system,sans-serif}main{max-width:1050px;margin:auto;padding:30px 20px 70px}a{color:var(--green);overflow-wrap:anywhere}h1{font-size:clamp(28px,4vw,43px);line-height:1.4;letter-spacing:-.03em;margin:8px 0 18px}h2{font-size:23px;margin:0 0 9px;line-height:1.5}h3{font-size:18px;margin:0;line-height:1.5}p{margin:7px 0 13px}.eyebrow{font-size:12px;letter-spacing:.08em;color:var(--green);font-weight:bold}.hero,.note,.card,.gate,.history{padding:22px;border:1px solid var(--line);border-radius:13px;background:var(--paper);margin-bottom:15px}.hero{border-top:5px solid var(--green)}.small,.meta{font-size:12px;color:var(--muted)}.facts{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.facts span{background:#eaf0e8;border-radius:7px;padding:8px 12px;font-size:13px}.policy{background:#fbf1da;border-left:4px solid #b48b3d;padding:12px 16px;border-radius:7px;font-size:14px}nav{position:sticky;top:0;z-index:5;display:flex;gap:8px;overflow:auto;background:#f0f2eef5;padding:11px 0;margin:18px 0 26px}nav a{white-space:nowrap;text-decoration:none;background:white;padding:8px 12px;border:1px solid var(--line);border-radius:7px;font-size:13px}.zone{margin:35px 0}.zone-head{padding:18px 20px;border-radius:10px;background:var(--pale);margin-bottom:15px}.zone-head.wait{background:#f2ecdf}.zone-head.done{background:#e4e8e3}.zone-head.running{background:#fff0d0}.zone-head p{font-size:14px;margin-bottom:0}.card{border-left:5px solid var(--green);padding:18px 21px}.card.waiting{border-left-color:#b9b9a6}.card.running{border-left-color:#bd8f3a}.card.done{border-left-color:#a8b9ab}.top{display:flex;gap:14px;align-items:flex-start}.id{min-width:87px;font:700 16px/1.65 ui-monospace,monospace;color:var(--green)}.badge{display:inline-block;margin:7px 0;background:#edf0e9;border-radius:4px;padding:2px 7px;font-size:12px}.conditions{font-size:13px;margin:7px 0;overflow-wrap:anywhere}.writes{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:12px}button,select{font:inherit;font-size:13px;border:1px solid var(--line);border-radius:7px;padding:9px 12px;background:white;color:var(--ink);max-width:100%}button{cursor:pointer}button.copy{background:var(--green);border-color:var(--green);color:white}button:disabled{cursor:not-allowed;background:#e8ece5;color:#68746c}label{font-size:12px}.result{font-size:13px;color:var(--green)}summary{cursor:pointer;color:var(--muted);font-size:13px}details{margin-top:13px}textarea{width:100%;height:390px;font:13px/1.8 ui-monospace,monospace;border:1px solid var(--line);border-radius:7px;padding:13px;resize:vertical;margin-top:10px;background:white}.gate{background:#faf5e5}.gate input{width:18px;height:18px;vertical-align:middle}.gate label{font-size:14px}.empty{padding:13px;color:var(--muted);font-size:13px}.record{border-bottom:1px solid var(--line);padding:7px 0;font-size:13px}footer{font-size:12px;color:var(--muted);margin-top:25px}@media(max-width:640px){main{padding:18px 12px 50px}.hero,.note,.card,.gate,.history{padding:17px}.top{display:block}.id{display:block;margin-bottom:6px}.facts{gap:7px}.facts span{font-size:12px}h2{font-size:21px}.zone-head{padding:15px}.actions{gap:8px}}
</style></head><body><main>
<div class="eyebrow">FC東京 × 柏レイソル / 制作指揮書 v6</div><section class="hero"><h1>この区切りの中は、<br>同時に送ってOK。</h1><p>下の<strong>「同時に送ってよい指示」</strong>に並ぶカードを、それぞれ新しいチャットへ1回送ってください。互いの終了を待つ必要はありません。</p><div class="facts"><span>問いの候補 <strong>344件</strong></span><span>柏の名鑑 <strong>25人 保存済み</strong></span><span>固定記事 <strong>44 / 64問 執筆済み</strong></span></div><div class="policy"><strong>あなた自身の逸話は今回不要。</strong> 選手・監督・クラブ・競技の逸話は引き続き調べます。旧野球ガイドの「製作者のエピソード」は引き継ぎません。</div><p class="meta" id="snapshot"></p></section>
<nav aria-label="進行状況の区切り"><a href="#zone-ready">同時に送ってよい指示</a><a href="#zone-running">別チャットで作業中</a><a href="#zone-waiting">先行成果を待つ指示</a><a href="#zone-done">GitHub保存済み・再送不要</a><a href="https://github.com/SideBySite/guide/tree/main/events/20261021-fctokyo-kashiwa/docs/prompt-pack" target="_blank" rel="noopener">GitHubのまとめ</a></nav>
<section class="note"><p><strong>コピー → 別チャットへ送付 → 「別チャットで作業中」と記録。</strong> 担当原稿とstatusのGitHub保存を確認してから「成果の保存を確認した」へ変えます。コピーしただけでは後工程を開きません。</p><p class="small">GitHubで保存を確認した28担当は初期状態から反映しています。その後の記録はこのブラウザ内の手動記録です。前のHTMLのチェックを自動で完了扱いにはしません。</p><div id="summary" class="small" aria-live="polite"></div></section>
<section class="zone" id="zone-ready"><div class="zone-head"><h2>同時に送ってよい指示</h2><p>この区切り内のカード同士は、別チャットへ同時に送ってOKです。既に送った担当は重複送信せず、作業中と記録してください。</p></div><div id="ready-cards"></div></section>
<section class="zone" id="zone-running"><div class="zone-head running"><h2>別チャットで作業中</h2><p>再送せずに、そのチャットの成果を待ちます。先行条件がそろった別のカードは並行して進められます。</p></div><div id="running-cards"></div></section>
<section class="zone" id="zone-waiting"><div class="zone-head wait"><h2>先行成果を待つ指示</h2><p>この区切りのカードは、まだ送らないでください。各カードの「まだ必要な成果」が保存されると、上の区切りへ移ります。</p></div><div id="waiting-cards"></div></section>
<div id="gates"></div>
<section class="zone" id="zone-done"><div class="zone-head done"><h2>GitHub保存済み・再送不要</h2><p>確認した担当の記録です。本文の保存と、逸話・推敲・最終確認の終了は別々に判定しています。</p></div><details><summary>保存済みの担当と指示本文を見る</summary><div id="done-cards"></div></details></section>
<section class="history"><h2>初期工程の記録</h2><div id="records"></div></section><footer>更新後も最大3人ずつ。FC東京はFCT-PREPで候補表と実名担当を準備します。保存済みカードを送り直す必要はありません。</footer>
</main><script id="data" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('data').textContent),jobs=new Map(data.tasks.map(t=>[t.id,t])),verified=new Set(data.tasks.filter(t=>t.verified_complete).map(t=>t.id)),state={},prefix='soccer-guide-v6-';
for(const t of [...data.tasks,...data.gates]){try{state[t.id]=localStorage.getItem(prefix+t.id)||''}catch{state[t.id]=''}if(verified.has(t.id))state[t.id]='done'}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isDone=id=>state[id]==='done',missing=t=>t.depends_on.filter(id=>!isDone(id)),ready=t=>!missing(t).length&&!['done','running'].includes(state[t.id]);
const link=id=>'<a href="#'+(jobs.has(id)?'task-':'gate-')+esc(id)+'">'+esc(id)+'</a>';
function storeState(id,value){if(verified.has(id))return;state[id]=value;try{localStorage.setItem(prefix+id,value)}catch{}}
function card(t){const id=t.id,s=state[id],miss=missing(t),r=ready(t),successors=data.tasks.filter(x=>x.depends_on.includes(id)),proof=t.completion_evidence;
 const status=verified.has(id)?'mainの実成果を確認済み':s==='done'?'この端末で保存を確認済み':s==='running'?'別チャットで作業中':r?'別チャットへ送ってOK':'先行成果を待ちます';
 const controls=verified.has(id)?'<span class="small">再送不要。'+(proof?proof.prs.map(n=>'<a href="https://github.com/SideBySite/guide/pull/'+n+'" target="_blank" rel="noopener">PR #'+n+'</a>').join('・'):'')+'</span>':'<button class="copy" data-copy="'+id+'" '+(!r?'disabled':'')+'>この担当の指示をコピー</button><label>送付と保存の記録 <select data-progress="'+id+'"><option value="" '+(!s?'selected':'')+'>まだ別チャットへ送っていない</option><option value="running" '+(s==='running'?'selected':'')+' '+(!r&&s!=='running'?'disabled':'')+'>別チャットで作業中</option><option value="done" '+(s==='done'?'selected':'')+'>成果の保存を確認した</option></select></label>';
 return '<article class="card '+(s==='done'?'done':s==='running'?'running':r?'ready':'waiting')+'" id="task-'+id+'" data-id="'+id+'"><div class="top"><span class="id">'+esc(id)+'</span><div><h3>'+esc(t.title)+'</h3><span class="badge">'+status+'</span></div></div><div class="conditions"><b>まだ必要な成果：</b>'+(miss.length?miss.map(link).join('・'):'なし')+'</div><div class="conditions"><b>先に必要な担当の記録：</b>'+(t.depends_on.length?t.depends_on.map(d=>link(d)+(isDone(d)?'（保存確認済み）':'')).join('・'):'独立して開始できます')+'</div><div class="conditions"><b>この担当の保存後に進む：</b>'+(successors.length?successors.map(x=>link(x.id)).join('・'):'指示本文の引き継ぎ先')+'</div><div class="writes">編集範囲：'+esc((t.writes||[]).join(' / '))+'</div><div class="actions">'+controls+'</div><div class="result" id="result-'+id+'" aria-live="polite"></div><details><summary>指示本文を読む'+(!r?'（閲覧用）':'')+'</summary><textarea readonly aria-label="'+id+'の指示全文">'+esc(t.prompt)+'</textarea></details></article>'}
function draw(){
 const buckets={ready:[],running:[],waiting:[],done:[]};for(const t of data.tasks){const s=state[t.id];buckets[s==='done'?'done':s==='running'?'running':ready(t)?'ready':'waiting'].push(t)}
 for(const [zone,list]of Object.entries(buckets))document.getElementById(zone+'-cards').innerHTML=list.length?list.map(card).join(''):'<p class="empty">この区切りに該当する担当はありません。</p>';
 document.getElementById('snapshot').textContent='GitHub確認：'+data.snapshot.checked_at+' ／ 確認コミット '+data.snapshot.commit.slice(0,12)+'。以後の変更は手動記録です。';
 document.getElementById('summary').textContent='同時に送ってよい指示 '+buckets.ready.length+'件 ／ 別チャットで作業中 '+buckets.running.length+'件 ／ 先行成果を待つ指示 '+buckets.waiting.length+'件 ／ 保存確認 '+buckets.done.length+'件';
 document.getElementById('gates').innerHTML=data.gates.map(g=>{const disabled=!isDone('00-J');return '<section class="gate" id="gate-'+g.id+'"><label><input type="checkbox" data-gate="'+g.id+'" '+(isDone(g.id)?'checked ':'')+(disabled?'disabled ':'')+'> '+esc(g.title)+'</label><p class="small">'+esc(g.description)+'</p><p class="small">00-Jの保存後に、生成された追加担当の実成果を確認して記録します。</p><a href="'+g.url+'" target="_blank" rel="noopener">追加担当の入口</a></section>'}).join('');
 document.getElementById('records').innerHTML=data.completed_records.map(x=>'<div class="record"><strong>'+x.id+'</strong>　'+esc(x.evidence)+'</div>').join('');
 document.querySelectorAll('[data-progress]').forEach(el=>el.addEventListener('change',()=>{const id=el.dataset.progress,t=jobs.get(id),pos=scrollY;if(el.value==='done'&&missing(t).length){document.getElementById('result-'+id).textContent='先に必要な成果の保存を確認してから記録してください。';el.value=state[id]||'';return}storeState(id,el.value);draw();scrollTo(0,pos)}));
 document.querySelectorAll('[data-copy]').forEach(el=>el.addEventListener('click',()=>copyPrompt(el.dataset.copy)));
 document.querySelectorAll('[data-gate]').forEach(el=>el.addEventListener('change',()=>{storeState(el.dataset.gate,el.checked?'done':'');draw()}));
}
async function copyPrompt(id){const t=jobs.get(id);if(!ready(t))return;const a=document.getElementById('task-'+id).querySelector('textarea');try{await navigator.clipboard.writeText(t.prompt);document.getElementById('result-'+id).textContent='コピーしました。送付したら「別チャットで作業中」に記録してください。'}catch{document.getElementById('task-'+id).querySelector('details').open=true;a.focus();a.select();let ok=false;try{ok=document.execCommand('copy')}catch{}document.getElementById('result-'+id).textContent=ok?'コピーしました。送付後に作業中と記録してください。':'全文を選択しました。コピー操作をしてください。'}}
draw();
</script></body></html>'''
(P/'index.html').write_text(page.replace('__DATA__',payload))
print('Rendered',len(m['tasks']),'tasks,',sum(bool(t.get('verified_complete')) for t in m['tasks']),'verified')
